  bool _isWorking = false;

  static const _cyan = Color(0xFF4AC9E3);
  static const _darkGrey = Color(0xFF353535);

  Future<void> _submit() async {
    setState(() => _isWorking = true);
    try {
      final result =
          await ref.read(claimRepositoryProvider).submit();
      if (!mounted) return;
      // Navigation follows the RESULT, never the tap.
      if (result.needsReview) context.push('/claim-review');
    } finally {
      if (mounted) setState(() => _isWorking = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return SizedBox(
      width: double.infinity,
      child: ElevatedButton(
        // Action button: disabled while working, spinner inside.
        onPressed: _isWorking ? null : _submit,
        style: ElevatedButton.styleFrom(
          backgroundColor: _cyan,
          foregroundColor: _darkGrey,
          padding: const EdgeInsets.symmetric(vertical: 16),
